\begin{tikzpicture}[font=\sffamily]
    \begin{axis}[
        xmin=0, xmax=3.0,
        ymin=-8, ymax=12,
        xtick={0,0.5,1.0,1.5,2.0,2.5,3.0},
        xticklabels={0,0.5,1.0,1.5,2.0,2.5,},
        ytick={-5,0,5,10},
        xlabel={time / s},
        ylabel={velocity / m/s},
        axis x line=center,
        axis y line=center,
        xlabel style={right},
        ylabel style={above},
        grid=both,
        grid style={line width=0.1pt, gray!30},
        major grid style={line width=0.3pt, gray!50},
        width=12cm, height=8cm,
        every axis x label/.style={at={(current axis.right of origin)},anchor=west},
        every axis y label/.style={at={(current axis.above origin)},anchor=south}
    ]

        % Line from origin to X(1.0, 10)
        \addplot[thick, domain=0:1.0] {10*x};

        % Dashed line from X(1.0, 10) to Y(1.2, -6)
        \addplot[thick, dashed, domain=1.0:1.2] {-80*x + 90};

        % Line from Y(1.2, -6) to Z(1.8, 0)
        \addplot[thick, domain=1.2:1.8] {10*x - 18};

        % Labels for points X, Y, Z
        \node[above right] at (axis cs:1.0, 10) {X};
        \node[below left] at (axis cs:1.2, -6) {Y};
        \node[above right] at (axis cs:1.8, 0) {Z};

        % Coordinate markers for key points
        \fill (axis cs:1.0, 10) circle (1.5pt);
        \fill (axis cs:1.2, -6) circle (1.5pt);
        \fill (axis cs:1.8, 0) circle (1.5pt);

    end{axis}

    % Caption below the figure
    \node at (6.2,-1.2) {Fig. 1.1};

\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily]
    \begin{axis}[
        xmin=0, xmax=3.0,
        ymin=-8, ymax=12,
        xtick={0,0.5,1.0,1.5,2.0,2.5,3.0},
        xticklabels={0,0.5,1.0,1.5,2.0,2.5,3.0},
        ytick={-5,0,5,10},
        xlabel={time / s},
        ylabel={velocity / m/s},
        axis x line=center,
        axis y line=center,
        grid=both,
        grid style={line width=0.1pt, gray!30},
        major grid style={line width=0.3pt, gray!50},
        width=12cm, height=8cm,
        xlabel style={at={(current axis.right of origin)}, anchor=west},
        ylabel style={at={(current axis.above origin)}, anchor=south}
    ]

        % Line from origin to X(1.0, 10)
        \addplot[thick, domain=0:1.0, samples=2] {10*x};

        % Dashed line from X(1.0, 10) to Y(1.2, -6)
        \addplot[thick, dashed, domain=1.0:1.2, samples=2] {-80*x + 90};

        % Line from Y(1.2, -6) to Z(1.8, 0)
        \addplot[thick, domain=1.2:1.8, samples=2] {10*x - 18};

        % Labels for points X, Y, Z
        \node[above right] at (axis cs:1.0, 10) {X};
        \node[below left] at (axis cs:1.2, -6) {Y};
        \node[above right] at (axis cs:1.8, 0) {Z};

        % Coordinate markers for key points
        \fill (axis cs:1.0, 10) circle (1.5pt);
        \fill (axis cs:1.2, -6) circle (1.5pt);
        \fill (axis cs:1.8, 0) circle (1.5pt);

    end{axis}

    % Caption below the figure
    \node at (6.2,-1.2) {Fig. 1.1};

\end{tikzpicture}
